import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import {
  FilterRegistry,
  PerformanceToolFilterDataTransformer,
} from 'domain/Filter';
import type {
  FilterDataStructure,
  FilterForm,
  FilterPage,
  FiltersState,
  UpdateFormPayload,
  UpdateFormValuePayload,
} from 'models/Filters';
import {
  cascadeCommercialBrandDependentDimensionsToBaseline,
  reconcileCommercialBrandDependentDimensions,
} from 'pages/pillars/ValueCreation/CommercialResults/commercialResultsFilterReconciliation';
import {
  getCommercialPresetSkeletonFieldKeys,
  resolveCommercialResultsRefreshTier,
} from 'pages/pillars/ValueCreation/CommercialResults/commercialResultsRefreshMeta';
import { COMMERCIAL_RESULTS_PAGE_NAME } from 'pages/pillars/ValueCreation/CommercialResults/constants';

import { createInitialFilterPage } from './constants';
import {
  loadFilters,
  refreshCommercialResultsFilterData,
} from './thunk/filtersThunk';

const noPageFoundError = 'Filters: Page not found';

const cloneFilterSnapshot = <T>(value: T): T =>
  JSON.parse(JSON.stringify(value)) as T;

function captureCommercialInitialPresetSnapshot(
  page: FilterPage,
  cached: boolean | undefined,
  dataFilters: FilterDataStructure | undefined,
): void {
  if (cached || !dataFilters) return;
  page.commercialInitialPresetSnapshot = {
    dataFilters: cloneFilterSnapshot(page.dataFilters),
    rawData: cloneFilterSnapshot(page.rawData),
    defaults: cloneFilterSnapshot(page.defaults),
    form: cloneFilterSnapshot(page.form),
  };
}

const isPerformanceToolData = (rawData: any): boolean =>
  !!rawData && PerformanceToolFilterDataTransformer.isValidFormat(rawData);

const resolveNavigatedKpi = (previousKpi: any, fallback: any): string =>
  String(previousKpi || fallback || '').toLowerCase();

const resolvePageFilters = (
  currentPage: FilterPage | undefined,
  previousPage: FilterPage | undefined,
  page: FilterPage,
  isPerformanceTool: boolean,
) => {
  const resolved = FilterRegistry.resolveFilterCollisions(
    currentPage,
    previousPage,
    page.defaults,
  );

  if (!isPerformanceTool) {
    page.defaults = { ...resolved };
  }
  page.form = { ...resolved };
  page.applied = { ...resolved };
};

const computeDynamicDataFilters = (
  page: FilterPage,
  kpi: string,
  currentForm?: FilterForm,
) => {
  if (!isPerformanceToolData(page.rawData)) {
    return page.dataFilters || {};
  }
  return PerformanceToolFilterDataTransformer.transform(
    page.rawData,
    kpi,
    currentForm,
  );
};

type LoadFiltersFulfilledContext = {
  cached: boolean | undefined;
  dataFilters: FilterDataStructure | undefined;
  rawData: unknown;
  defaultKpi: string | undefined;
  isPerformanceTool: boolean;
  isRefresh: boolean;
};

function applyLoadFiltersFulfilledPageData(
  page: FilterPage,
  ctx: LoadFiltersFulfilledContext,
): void {
  const {
    cached,
    dataFilters,
    rawData,
    defaultKpi,
    isPerformanceTool,
    isRefresh,
  } = ctx;

  if (!cached && dataFilters) {
    page.rawData = rawData;

    if (isPerformanceTool && !page.defaultKpi) {
      const initialKpi = resolveNavigatedKpi(
        defaultKpi ||
          (rawData as FilterDataStructure)?.kpis?.values?.[0]?.value,
        '',
      );
      page.dataFilters = PerformanceToolFilterDataTransformer.transform(
        rawData,
        initialKpi,
      );
    } else if (!isPerformanceTool) {
      page.dataFilters = dataFilters;
    }

    if (!isRefresh) {
      page.defaults = FilterRegistry.calculateDefaults(page.dataFilters);
    }
  }
}

function resolveLoadFiltersFulfilledForm(
  state: FiltersState,
  page: FilterPage,
  pageName: string,
  ctx: Pick<
    LoadFiltersFulfilledContext,
    'defaultKpi' | 'isPerformanceTool' | 'isRefresh'
  >,
): void {
  const { defaultKpi, isPerformanceTool, isRefresh } = ctx;
  if (isRefresh) return;

  if (isPerformanceTool) {
    const previousKpi = state.pages[state.previousPage]?.applied?.kpis;
    const navigatedKpi = resolveNavigatedKpi(
      defaultKpi || previousKpi,
      page.defaults?.kpis,
    );
    page.defaultKpi = navigatedKpi;
    page.defaults = { ...page.defaults, kpis: navigatedKpi };
  }

  resolvePageFilters(
    state.pages[pageName],
    state.pages[state.previousPage],
    page,
    isPerformanceTool,
  );
}

const initialState: FiltersState = {
  pages: {},
  currentPage: null,
  previousPage: null,
};

export const filterSlice = createSlice({
  name: 'filters',
  initialState,
  reducers: {
    setCurrentPage: (state, action: PayloadAction<string>) => {
      if (state.currentPage === action.payload) {
        return;
      }

      state.previousPage = state.currentPage;
      state.currentPage = action.payload;

      const newPage = state.pages[action.payload];
      const hasDefaults =
        newPage?.status === 'loaded' &&
        Object.keys(newPage.defaults).length > 0;

      if (!hasDefaults) return;

      const isPerformanceTool = isPerformanceToolData(newPage.rawData);

      if (isPerformanceTool) {
        const previousKpi = state.pages[state.previousPage]?.applied?.kpis;
        const navigatedKpi = resolveNavigatedKpi(
          previousKpi,
          newPage.defaultKpi,
        );

        newPage.dataFilters = PerformanceToolFilterDataTransformer.transform(
          newPage.rawData,
          navigatedKpi,
        );
        newPage.defaultKpi = navigatedKpi;
        newPage.defaults = {
          ...FilterRegistry.calculateDefaults(newPage.dataFilters),
          kpis: navigatedKpi,
        };
      }

      resolvePageFilters(
        state.pages[action.payload],
        state.pages[state.previousPage],
        newPage,
        isPerformanceTool,
      );
    },

    updateFormValue: (state, action: PayloadAction<UpdateFormValuePayload>) => {
      const { key, value } = action.payload;
      const currentPage = state.currentPage;

      if (!currentPage || !state.pages[currentPage]) {
        console.warn(noPageFoundError);
        return;
      }

      const page = state.pages[currentPage];
      const form = page.form;
      const kpi = key === 'kpis' ? String(value) : String(form?.kpis);
      const dataFilters = computeDynamicDataFilters(page, kpi, {
        ...form,
        [key]: value,
      });

      const previousBrand = form?.brands;

      page.form = FilterRegistry.resolveCascadingUpdates(
        dataFilters,
        form,
        key,
        value,
      );

      if (
        currentPage === COMMERCIAL_RESULTS_PAGE_NAME &&
        key === 'brands' &&
        String(previousBrand ?? '') !== String(value ?? '')
      ) {
        page.form = cascadeCommercialBrandDependentDimensionsToBaseline(
          dataFilters,
          page.form,
        );
      }

      if (key === 'kpis') {
        page.dataFilters = dataFilters;
      }
    },

    resetAndApplyDefaults: (
      state,
      action: PayloadAction<UpdateFormPayload>,
    ) => {
      const { form } = action.payload;
      const currentPage = state.currentPage;

      if (!currentPage) {
        return;
      }

      const page = state.pages[currentPage];

      if (!page) {
        return;
      }

      page.form = { ...form };
    },

    applyFilters: (state) => {
      const currentPage = state.currentPage;

      if (!currentPage) {
        console.warn(noPageFoundError);
        return;
      }

      const page = state.pages[currentPage];

      if (!page) {
        console.warn(noPageFoundError);
        return;
      }

      page.applied = { ...page.form };
      page.lastUpdated = Date.now();
    },

    resetToDefaults: (state) => {
      const currentPage = state.currentPage;

      if (!currentPage) {
        console.warn(noPageFoundError);
        return;
      }

      const page = state.pages[currentPage];

      if (!page) {
        console.warn(noPageFoundError);
        return;
      }

      page.form = { ...page.defaults };
      page.applied = { ...page.defaults };
      page.lastUpdated = Date.now();
    },

    bulkResetDraftFormFromDefaults: (
      state,
      action: PayloadAction<{ defaults: FilterForm }>,
    ) => {
      const currentPage = state.currentPage;

      if (!currentPage || !state.pages[currentPage]) {
        console.warn(noPageFoundError);
        return;
      }

      const page = state.pages[currentPage];
      const { defaults: defaultsPayload } = action.payload;

      if (
        currentPage === COMMERCIAL_RESULTS_PAGE_NAME &&
        page.commercialInitialPresetSnapshot
      ) {
        const snap = page.commercialInitialPresetSnapshot;
        page.dataFilters = cloneFilterSnapshot(snap.dataFilters);
        page.rawData = cloneFilterSnapshot(snap.rawData);
        page.defaults = cloneFilterSnapshot(snap.defaults);
        page.form = cloneFilterSnapshot(snap.form);
        page.lastUpdated = Date.now();
        page.lastCommercialRefreshTier = resolveCommercialResultsRefreshTier(
          page.form,
        );
        return;
      }

      const registry = FilterRegistry.getInstance();
      let form = { ...page.form };

      for (const key of registry.getOrderedKeys()) {
        if (!(key in defaultsPayload)) continue;
        if (!registry.isResettable(key)) continue;
        const value = defaultsPayload[key];
        const kpi = key === 'kpis' ? String(value) : String(form?.kpis);
        const dataFilters = computeDynamicDataFilters(page, kpi, {
          ...form,
          [key]: value,
        });
        form = FilterRegistry.resolveCascadingUpdates(
          dataFilters,
          form,
          key,
          value,
        );
        if (key === 'kpis') {
          page.dataFilters = dataFilters;
        }
      }

      page.form = form;
    },

    setFilterVisibility: (
      state,
      action: PayloadAction<{ page: string; isHidden: boolean }>,
    ) => {
      const { page, isHidden } = action.payload;
      if (state.pages[page]) {
        state.pages[page].isHidden = isHidden;
      }
    },
  },

  extraReducers: (builder) => {
    builder
      .addCase(loadFilters.pending, (state, action) => {
        const { pageName } = action.meta.arg;

        if (!state.pages[pageName]) {
          state.pages[pageName] = createInitialFilterPage();
        }

        const page = state.pages[pageName];

        if (page.status === 'idle' || page.status === undefined) {
          page.status = 'loading';
        }

        if (pageName === COMMERCIAL_RESULTS_PAGE_NAME) {
          const targetTier = resolveCommercialResultsRefreshTier(page.form);
          page.commercialPresetRefresh = {
            pending: true,
            skeletonFieldKeys: getCommercialPresetSkeletonFieldKeys(
              targetTier,
              page.lastCommercialRefreshTier,
            ),
          };
        }
      })

      .addCase(loadFilters.fulfilled, (state, action) => {
        const { pageName, dataFilters, cached, rawData, defaultKpi } =
          action.payload;
        const page = state.pages[pageName];

        if (!page) return;

        if (!cached && !dataFilters) {
          page.status = 'error';
          return;
        }

        const isPerformanceTool = isPerformanceToolData(rawData);
        const isRefresh = isPerformanceTool && !!page.defaultKpi;
        const fulfilledCtx: LoadFiltersFulfilledContext = {
          cached,
          dataFilters,
          rawData,
          defaultKpi,
          isPerformanceTool,
          isRefresh,
        };

        applyLoadFiltersFulfilledPageData(page, fulfilledCtx);
        resolveLoadFiltersFulfilledForm(state, page, pageName, fulfilledCtx);

        page.status = 'loaded';

        if (pageName === COMMERCIAL_RESULTS_PAGE_NAME) {
          delete page.commercialPresetRefresh;
          captureCommercialInitialPresetSnapshot(page, cached, dataFilters);
          if (!cached && dataFilters) {
            page.lastCommercialRefreshTier =
              resolveCommercialResultsRefreshTier(page.form);
          }
        }
      })

      .addCase(refreshCommercialResultsFilterData.pending, (state) => {
        const page = state.pages[COMMERCIAL_RESULTS_PAGE_NAME];
        if (!page) return;
        const targetTier = resolveCommercialResultsRefreshTier(page.form);
        page.commercialPresetRefresh = {
          pending: true,
          skeletonFieldKeys: getCommercialPresetSkeletonFieldKeys(
            targetTier,
            page.lastCommercialRefreshTier,
          ),
        };
      })

      .addCase(
        refreshCommercialResultsFilterData.fulfilled,
        (state, action) => {
          const { pageName, dataFilters, rawData } = action.payload;
          if (pageName !== COMMERCIAL_RESULTS_PAGE_NAME) return;
          const page = state.pages[pageName];
          if (!page || !dataFilters) return;
          page.rawData = rawData ?? page.rawData;
          page.dataFilters = dataFilters;
          page.form = reconcileCommercialBrandDependentDimensions(
            dataFilters,
            page.form,
          );
          page.applied = reconcileCommercialBrandDependentDimensions(
            dataFilters,
            page.applied,
          );
          page.lastCommercialRefreshTier = resolveCommercialResultsRefreshTier(
            page.form,
          );
          delete page.commercialPresetRefresh;
        },
      )

      .addCase(refreshCommercialResultsFilterData.rejected, (state) => {
        const page = state.pages[COMMERCIAL_RESULTS_PAGE_NAME];
        if (page) {
          delete page.commercialPresetRefresh;
        }
      })

      .addCase(loadFilters.rejected, (state, action) => {
        const { pageName } = action.meta.arg;
        const page = state.pages[pageName];

        if (page) {
          page.status = 'error';
          delete page.commercialPresetRefresh;
        }
      });
  },
});

